"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { useState, useEffect } from "react"
import { cn } from "@/lib/utils"
import { Home, Maximize, Smartphone, Menu, X, Save } from "lucide-react"
import { Button } from "@/components/ui/button"

const menuItems = [
  {
    name: "메인홈",
    href: "/",
    icon: Home,
  },
  {
    name: "사이트별 썸네일 크기 확인",
    href: "/thumbnail-size",
    icon: Maximize,
  },
  {
    name: "작품 스크롤 확인(모바일용)",
    href: "/mobile-scroll",
    icon: Smartphone,
  },
]

function MouseIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 100 100"
      className={className}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      {/* 둥근 귀 */}
      <circle cx="25" cy="28" r="25" fill="currentColor" />
      <circle cx="75" cy="28" r="25" fill="currentColor" />
      <circle cx="25" cy="28" r="16" fill="#F9A8D4" />
      <circle cx="75" cy="28" r="16" fill="#F9A8D4" />

      {/* 통통한 얼굴 모양 (납작한 동그라미) */}
      <ellipse
        cx="50"
        cy="62"
        rx="42"
        ry="28"
        fill="currentColor"
      />

      {/* 발그레 볼 */}
      <ellipse cx="32" cy="65" rx="6" ry="4" fill="#F9A8D4" opacity="0.6" />
      <ellipse cx="68" cy="65" rx="6" ry="4" fill="#F9A8D4" opacity="0.6" />

      {/* 초롱초롱 눈 */}
      <circle cx="40" cy="56" r="4.5" fill="var(--background, #fff)" />
      <circle cx="60" cy="56" r="4.5" fill="var(--background, #fff)" />

      {/* 입 모양 w */}
      <path
        d="M45 64 Q 47.5 68 50 64 Q 52.5 68 55 64"
        stroke="var(--background, #fff)"
        strokeWidth="2.5"
        strokeLinecap="round"
        fill="none"
      />
    </svg>
  )
}

export function Sidebar() {
  const pathname = usePathname()
  const [isOpen, setIsOpen] = useState(false)

  // 페이지 이동 시 사이드바 닫기
  useEffect(() => {
    setIsOpen(false)
  }, [pathname])

  return (
    <>
      {/* 햄버거 메뉴 버튼 */}
      <Button
        variant="ghost"
        size="icon"
        className="fixed left-4 top-4 z-50 h-12 w-12 rounded-lg border border-border bg-card text-foreground hover:bg-primary hover:text-primary-foreground"
        onClick={() => setIsOpen(!isOpen)}
      >
        {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
      </Button>

      {/* 오버레이 */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50"
          onClick={() => setIsOpen(false)}
        />
      )}

      {/* 사이드바 */}
      <aside
        className={cn(
          "fixed left-0 top-0 z-40 flex h-screen w-72 flex-col border-r border-sidebar-border bg-sidebar transition-transform duration-300",
          isOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <div className="flex h-20 items-center justify-center border-b border-sidebar-border">
          <Link href="/" className="flex items-center gap-3" onClick={() => setIsOpen(false)}>
            <MouseIcon className="h-10 w-10 text-primary" />
            <span className="text-xl font-bold tracking-wider text-sidebar-foreground">
              웹툰 업로더
            </span>
          </Link>
        </div>

        <nav className="flex-1 px-4 py-6">
          <ul className="flex flex-col gap-2">
            {menuItems.map((item) => {
              const isActive = pathname === item.href
              return (
                <li key={item.href}>
                  <Link
                    href={item.href}
                    className={cn(
                      "flex items-center gap-3 rounded-lg px-4 py-3 text-sm font-medium transition-all duration-200",
                      isActive
                        ? "bg-primary text-primary-foreground"
                        : "text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground"
                    )}
                    onClick={() => setIsOpen(false)}
                  >
                    <item.icon className="h-5 w-5" />
                    <span>{item.name}</span>
                  </Link>
                </li>
              )
            })}
          </ul>
        </nav>

        <div className="border-t border-sidebar-border p-4">
          <p className="text-center text-xs text-sidebar-foreground/50">
            &copy; 2024 웹툰 업로더
          </p>
        </div>
      </aside>
    </>
  )
}
